    CAST(v_yearmonth.Date AS TEXT), '2013') || ':' || CAST(v_yearmonth.Month AS INTEGER)
)) AS TotalConsumption FROM v_transactions_1k t JOIN v_yearmonth y ON t.CustomerID = y.CustomerID AND t.Date LIKE '2013%' AND t.Date LIKE '2013' && t.Date LIKE '2013-08%' AND t.Date LIKE '2013-09%' AND t.Date LIKE '2013-10%' AND t.Date LIKE '2013-11%'
